{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '살기 위한 거였는데'와 '멈추면 안 될 것 같아서'의 차이를 묻는 것은, 유기/불안정 스키마가 과거 생존 전략에서 현재 자동 패턴으로 전환된 과정을 직면하게 하는 질문임. 성장 경험에서 아버지의 예고 없는 사라짐과 어머니의 야간 근무로 형성된 불안정성이 이 구분의 출발점."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '착해야 하고, 엄마 기분 살피고, 조용히 있으면 안 갈 거라고' 생각했던 것은 '내가 사랑하는 사람은 결국 나를 떠날 것이다'라는 핵심 신념의 구체적 방어 전략이었음. 상담사가 이 신념의 과거 기능과 현재 기능을 구분하도록 유도."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/0"],
      "relevance": "'상대가 떠날 조짐이 없는지 항상 살펴야 하고, 조금이라도 멀어진 느낌이 들면 즉시 붙잡아야 한다'는 규칙이 내담자가 '아직까지도 하고 있다'고 인정한 행동의 원리. 상황 사례에서 답장 지연 시 메시지를 연달아 보내고 전화를 거는 것이 이 규칙의 현재 발현."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "'확인을 멈추면 아버지처럼 예고 없이 사라져 버릴 것이다'라는 부정적 가정이 '멈추면 안 될 것 같아서'라는 상담사의 질문과 직접 연결됨. 아버지가 '금방 온다'고 하고 돌아오지 않은 경험이 이 가정을 강화."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/0"],
      "relevance": "'계속 확인하고 더 잘하려 애쓰면 떠나는 것을 막을 수 있다'는 긍정적 가정이 '아직 필요해서인지'라는 상담사의 질문과 연결됨. 상황 사례에서 후회하면서도 같은 행동을 반복하는 것은 이 가정이 아직 유효하다고 느껴지기 때문."
    }
  ]
}

